// Both triggers end up here. The form sends its fields by label,
// the webhook sends a JSON body. Turn either into one clean lead.

// The business the replies are written for. Change these two lines for a client.
const BUSINESS = 'Khan M., AI automation for small businesses (support chatbots, email and document automation, video content repurposing)';
const SIGN_OFF = 'Khan';

return $input.all().map((item) => {
  const fromWebhook = item.json.body !== undefined;
  const src = fromWebhook ? item.json.body : item.json;
  const pick = (...keys) => {
    for (const key of keys) {
      const value = src[key];
      if (value !== undefined && value !== null && String(value).trim() !== '') {
        return String(value).trim();
      }
    }
    return '';
  };

  return {
    json: {
      name: pick('Name', 'name'),
      email: pick('Email', 'email').toLowerCase(),
      company: pick('Company', 'company'),
      budget: pick('Budget', 'budget') || 'Not given',
      message: pick('Message', 'message').slice(0, 4000),
      // A sender such as the website chat agent can name its channel and the business it answers for.
      source: fromWebhook ? (pick('source').slice(0, 40) || 'webhook') : 'website form',
      received_at: new Date().toISOString(),
      business: (fromWebhook && pick('business').slice(0, 200)) || BUSINESS,
      sign_off: (fromWebhook && pick('sign_off').slice(0, 80)) || SIGN_OFF,
    },
  };
});

