{
  "type": "object",
  "properties": {
    "category": {
      "type": "string",
      "enum": ["hot", "warm", "cold", "spam"],
      "description": "hot = clear need we offer, a budget or timeline, wants to talk soon. warm = real need but vague or no rush. cold = just curious or price shopping. spam = selling something to us, mass mailing, or unrelated."
    },
    "service": {
      "type": "string",
      "description": "Which of the business's services fits the request best, in 2 to 4 lowercase words (for example 'support chatbot' or 'teeth whitening'). 'other' if none fits."
    },
    "urgency": {
      "type": "string",
      "enum": ["high", "normal", "low"],
      "description": "high only if they mention a deadline, 'this week', or asks to talk now."
    },
    "summary": {
      "type": "string",
      "description": "One sentence, at most 25 words: who they are and what they want. Facts from the message only."
    },
    "reason": {
      "type": "string",
      "description": "At most 20 words: the facts from the message that decided the category."
    },
    "reply_draft": {
      "type": "string",
      "description": "Email reply for a person to review before sending. Required for hot, warm and cold leads. Empty string only for spam."
    }
  },
  "required": ["category", "service", "urgency", "summary", "reason", "reply_draft"]
}

