// Join the original lead with what the AI decided, and guard against odd output.
const NEXT_STEP = {
  hot: 'Call or reply today',
  warm: 'Reply today with questions',
  cold: 'Send short info reply',
  spam: 'Ignore',
};

return $input.all().map((item, index) => {
  const lead = $('Clean up the lead').itemMatching(index).json;
  const ai = item.json.output || {};
  const category = NEXT_STEP[ai.category] ? ai.category : 'warm';
  const reply = category === 'spam' ? '' : String(ai.reply_draft || '').trim();
  // The model sometimes skips the reply. Say so instead of leaving a silent blank.
  const nextStep = category !== 'spam' && !reply
    ? NEXT_STEP[category] + ' (no AI draft, write the reply by hand)'
    : NEXT_STEP[category];

  return {
    json: {
      received_at: lead.received_at,
      source: lead.source,
      name: lead.name,
      email: lead.email,
      company: lead.company,
      budget: lead.budget,
      message: lead.message,
      category,
      service: ai.service || 'other',
      urgency: ai.urgency || 'normal',
      summary: ai.summary || '',
      reason: ai.reason || '',
      reply_draft: reply,
      next_step: nextStep,
    },
  };
});

// Pass the full record on, not the row id the table returned.
return $input.all().map((item, index) => ({
  json: $('Build the lead record').itemMatching(index).json,
}));
